from collections import Counter

def is_possible_divide(nums, k):
    if len(nums) % k:
        return False
    count = Counter(nums)
    for num in sorted(nums):
        if count[num] > 0:
            need = count[num]
            for nxt in range(num, num + k):
                if count[nxt] < need:
                    return False
                count[nxt] -= need
    return True

