#include <bits/stdc++.h>
using namespace std;

bool isPossibleDivide(vector<int>& nums, int k) {
    if (nums.size() % k) return false;
    map<int, int> count;
    for (int v : nums) ++count[v];
    for (auto [num, need] : count) {
        while (count[num] > 0) {
            for (int nxt = num; nxt < num + k; ++nxt) {
                if (count[nxt] < count[num]) return false;
                count[nxt] -= count[num];
            }
        }
    }
    return true;
}

