import java.util.*;

class Solution {
    public boolean isPossibleDivide(int[] nums, int k) {
        if (nums.length % k != 0) return false;
        TreeMap<Integer, Integer> count = new TreeMap<>();
        for (int v : nums) count.merge(v, 1, Integer::sum);
        for (int num : new ArrayList<>(count.keySet())) {
            int need;
            while ((need = count.getOrDefault(num, 0)) > 0) {
                for (int nxt = num; nxt < num + k; ++nxt) {
                    int have = count.getOrDefault(nxt, 0);
                    if (have < need) return false;
                    if (have == need) count.remove(nxt); else count.put(nxt, have - need);
                }
            }
        }
        return true;
    }
}
